package com.ivomens.mcheli.gametest.snapshot;

import net.minecraft.server.level.ServerChunkCache;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.ChunkPos;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.LockSupport;

/**
 * A rectangle of chunks a recorded run keeps force-loaded: the weapon range, the golden course.
 * <p>
 * The game test server runs its ticks back to back without sleeping, and a test's time limit counts
 * ticks. Chunks are loaded and generated by worker threads, in wall time. A run that waited for its
 * chunks tick by tick therefore spent anywhere from a handful to well over a thousand of its ticks
 * on it, depending on how busy the machine was, and timed out on a slow two-core CI runner.
 * {@link #awaitReady} instead holds the server thread until the chunks tick entities, doing the
 * chunk work queued for the main thread meanwhile, so no game tick passes while they load.
 */
public final class ForcedArea {

    /** A load that takes longer than this is broken, not slow. */
    private static final long LOAD_LIMIT_NANOS = TimeUnit.MINUTES.toNanos(3);
    /** Pause while the main thread has nothing to do and the workers are still loading. */
    private static final long IDLE_PARK_NANOS = TimeUnit.MILLISECONDS.toNanos(1);

    private final ServerLevel level;
    private final List<ChunkPos> chunks;
    private final int y;

    /** Every chunk from {@code min} to {@code max}, both included; {@code y} is the height checked. */
    public ForcedArea(ServerLevel level, ChunkPos min, ChunkPos max, int y) {
        this.level = level;
        this.y = y;
        this.chunks = new ArrayList<>();
        for (int x = min.x; x <= max.x; x++) {
            for (int z = min.z; z <= max.z; z++) {
                this.chunks.add(new ChunkPos(x, z));
            }
        }
    }

    public void force(boolean forced) {
        for (ChunkPos chunk : this.chunks) {
            this.level.setChunkForced(chunk.x, chunk.z, forced);
        }
    }

    /** Whether every chunk of the area ticks entities. */
    public boolean ready() {
        for (ChunkPos chunk : this.chunks) {
            if (!this.level.isPositionEntityTicking(chunk.getMiddleBlockPosition(this.y))) {
                return false;
            }
        }
        return true;
    }

    /**
     * Blocks the server thread until the forced area ticks entities. Ticket changes, finished loads
     * and chunk status changes all arrive through the chunk cache's main thread queue, which is run
     * here the way a synchronous chunk load runs it.
     */
    public void awaitReady() {
        ServerChunkCache source = this.level.getChunkSource();
        long deadline = System.nanoTime() + LOAD_LIMIT_NANOS;
        while (!ready()) {
            if (System.nanoTime() - deadline > 0) {
                throw new IllegalStateException("the forced chunks did not load within "
                        + TimeUnit.NANOSECONDS.toSeconds(LOAD_LIMIT_NANOS) + " s");
            }
            if (!source.pollTask()) {
                LockSupport.parkNanos(IDLE_PARK_NANOS);
            }
        }
    }
}
